def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the repeated-row color strip that acts as the palette key.
    key_rows = set()
    replacement = None
    r = 0
    while r < h:
        end = r + 1
        while end < h and grid[end] == grid[r]:
            end += 1
        if end - r >= 2:
            colors = [c for c in grid[r] if c != 0]
            if 1 in colors:
                i = colors.index(1)
                if i > 0:
                    replacement = colors[i - 1]
                    key_rows.update(range(r, end))
                    break
        r = end

    if replacement is not None:
        for i in range(h):
            if i not in key_rows:
                for j in range(w):
                    if out[i][j] == 1:
                        out[i][j] = replacement
    return out
